/// <summary>
///    The <c>METTOReceiptListController</c> class is the controller class for the
///    <c>TO receipt list</c> report.
/// </summary>
class METTOReceiptListController extends SrsReportRunController implements BatchRetryable
{
}

Method.Source:
/// <summary>
/// Set prePromptModifyContract method
/// </summary>
protected void prePromptModifyContract()
{
    InventTransferTable         inventTransferTable;
    METTOReceiptListContract    contract = this.parmReportContract().parmRdpContract(); 

    if (this.parmArgs() || this.parmArgs().caller() || this.parmArgs().dataset() == tableNum(InventTransferTable) )
    {
        inventTransferTable = this.parmArgs().record();
    }
    if (inventTransferTable)
    {
        // Set the hidden parameter value.
        contract.parmRecordId(inventTransferTable.RecId);
    }
}

public static void main(Args _args)
{
    METTOReceiptListController  controller = new METTOReceiptListController();

    controller.parmReportName(ssrsReportStr(METTOReceiptListReport, Report));
    controller.parmArgs(_args);
    controller.startOperation();
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable() 
{
    return true;
}
